### 3.6. Loot en el suelo (`LootItem.cs`)
Armas y mejoras repartidas por el mapa.

```csharp
using UnityEngine;

public enum LootType { Weapon, Attachment }

public class LootItem : MonoBehaviour
{
    public LootType type;
    public WeaponBase weaponPrefab;      // si es arma
    public GameObject attachmentPrefab;  // si es mejora (mira, culata, cargador)
    public bool isGlowing = true;        // brillo meme para verse desde lejos

    void OnTriggerEnter(Collider other)
    {
        if (other.CompareTag("Player"))
        {
            var handler = other.GetComponent<WeaponHandler>();
            if (handler != null && type == LootType.Weapon)
                handler.AddWeapon(weaponPrefab);

            // si es attachment, se acopla al arma en mano
            Destroy(gameObject);
        }
    }
}
```

### 3.7. Sistema de mejoras / adjuntos (`AttachmentSystem.cs`)
Miras, culatas, cargadores que se acoplan al arma en mano.

```csharp
using UnityEngine;

public enum AttachmentType { Sight, Stock, Magazine, Barrel }

public class AttachmentSystem : MonoBehaviour
{
    public AttachmentType type;
    public GameObject model; // el cubo detallado de la mejora
    public Transform attachPoint; // punto del arma donde se acopla

    public void AttachTo(WeaponBase weapon)
    {
        // Instanciar modelo de mejora en el punto del arma
        var instance = Instantiate(model, attachPoint);
        instance.transform.localPosition = Vector3.zero;
        instance.transform.localRotation = Quaternion.identity;

        // Aplicar stats según tipo
        switch (type)
        {
            case AttachmentType.Sight:
                // reducir dispersión, añadir zoom
                break;
            case AttachmentType.Stock:
                // reducir retroceso, reducir movilidad
                break;
            case AttachmentType.Magazine:
                // más munición / recarga
                break;
        }
    }
}
```

