```csharp
using UnityEngine;

public class EyeOfPigeon : MonoBehaviour
{
    public Transform pigeonEye; // modelo del ojo gigante en el cielo
    public float warningTime = 6f; // segundos antes de comerte
    public float checkInterval = 0.2f;

    private Transform player;
    private float timer;
    private bool isWarning;
    private bool hasBeenEaten;

    void Update()
    {
        if (player == null) return;

        // El ojo sigue al jugador en el cielo (solo posición XZ, Y fija alta)
        Vector3 eyePos = new Vector3(player.position.x, 200f, player.position.z);
        pigeonEye.position = eyePos;
        pigeonEye.LookAt(player);

        if (isWarning && !hasBeenEaten)
        {
            timer += Time.deltaTime;
            if (timer >= warningTime)
                EatPlayer();
        }
    }

    public void StartWarning(Transform playerTransform)
    {
        player = playerTransform;
        isWarning = true;
        timer = 0;
        pigeonEye.gameObject.SetActive(true);
        Debug.Log("Vuelve atrás, grano de alpiste");
    }

    public void StopWarning()
    {
        player = null;
        isWarning = false;
        timer = 0;
        hasBeenEaten = false;
        pigeonEye.gameObject.SetActive(false);
    }

    void EatPlayer()
    {
        hasBeenEaten = true;
        isWarning = false;
        pigeonEye.gameObject.SetActive(false);

        // Muerte instantánea
        var dmg = player.GetComponent<DamageSystem>();
        if (dmg != null)
            dmg.TomarDaño(99999, false); // más que 1000 HP, muerte segura

        // Anuncio global
        Debug.Log($"[Chat] {player.name} fue comido por la Paloma Cósmica por creerse listo en la lava");
    }
}
